import{_ as o,C as n,o as d,c as i,j as r,a as e,E as l,w as s,a3 as h}from"./chunks/framework.EDt1A0Ag.js";const T=JSON.parse('{"title":"科学上网主流代理协议横评 2026 · SS / VLESS / Trojan / Hy2","description":"2026年主流代理协议深度横向测评。从加密机制、抗封锁能力、CPU开销、UDP传输及晚高峰吞吐率，全面对比Shadowsocks 2022、VLESS Reality、Trojan与Hysteria2。","frontmatter":{"title":"科学上网主流代理协议横评 2026 · SS / VLESS / Trojan / Hy2","description":"2026年主流代理协议深度横向测评。从加密机制、抗封锁能力、CPU开销、UDP传输及晚高峰吞吐率，全面对比Shadowsocks 2022、VLESS Reality、Trojan与Hysteria2。"},"headers":[],"relativePath":"tech/protocols.md","filePath":"tech/protocols.md","lastUpdated":1787499481000}'),y={name:"tech/protocols.md"},g={class:"flex items-center gap-2 mb-6"};function f(S,t,x,c,p,P){const a=n("LeafBadge");return d(),i("div",null,[t[4]||(t[4]=r("h1",{id:"🔬-科学上网主流协议对比-2026-·-ss-vless-trojan-hy2",tabindex:"-1"},[e("🔬 科学上网主流协议对比 2026 · SS / VLESS / Trojan / HY2 "),r("a",{class:"header-anchor",href:"#🔬-科学上网主流协议对比-2026-·-ss-vless-trojan-hy2","aria-label":'Permalink to "🔬 科学上网主流协议对比 2026 · SS / VLESS / Trojan / HY2"'},"​")],-1)),r("div",g,[l(a,{variant:"primary"},{default:s(()=>[...t[0]||(t[0]=[e("协议横评",-1)])]),_:1}),l(a,{variant:"amber"},{default:s(()=>[...t[1]||(t[1]=[e("VLESS Reality",-1)])]),_:1}),l(a,{variant:"wood"},{default:s(()=>[...t[2]||(t[2]=[e("Hysteria2 (QUIC)",-1)])]),_:1}),l(a,{variant:"accent"},{default:s(()=>[...t[3]||(t[3]=[e("Shadowsocks 2022",-1)])]),_:1})]),t[5]||(t[5]=h('<p>协议是网络数据在传输过程中的“打包规范与加密语言”。不同的协议在<strong>传输性能、抗审查伪装能力以及设备功耗</strong>上有着截然不同的表现。</p><hr><h2 id="📊-四大核心协议性能基准参数表" tabindex="-1">📊 四大核心协议性能基准参数表 <a class="header-anchor" href="#📊-四大核心协议性能基准参数表" aria-label="Permalink to &quot;📊 四大核心协议性能基准参数表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">协议名称</th><th style="text-align:left;">传输层基础</th><th style="text-align:left;">伪装与抗封锁能力</th><th style="text-align:left;">CPU 算力开销</th><th style="text-align:left;">劣质网络加速能力</th><th style="text-align:left;">推荐使用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Shadowsocks 2022</strong></td><td style="text-align:left;">TCP / UDP</td><td style="text-align:left;">⭐⭐⭐☆☆ (依赖专线内网)</td><td style="text-align:left;"><strong>极低 (硬件 AES 加速)</strong></td><td style="text-align:left;">⭐⭐⭐☆☆</td><td style="text-align:left;"><strong>IEPL / IPLC 专线首选</strong></td></tr><tr><td style="text-align:left;"><strong>VLESS (Reality)</strong></td><td style="text-align:left;">TCP + TLS</td><td style="text-align:left;">⭐⭐⭐⭐⭐ (借用大厂证书)</td><td style="text-align:left;">低</td><td style="text-align:left;">⭐⭐⭐⭐☆</td><td style="text-align:left;">公网直连 / 中转建站</td></tr><tr><td style="text-align:left;"><strong>Trojan</strong></td><td style="text-align:left;">HTTPS (标准 TLS)</td><td style="text-align:left;">⭐⭐⭐⭐☆ (完美伪装网页)</td><td style="text-align:left;">低</td><td style="text-align:left;">⭐⭐⭐⭐☆</td><td style="text-align:left;">追求稳定伪装与通用兼容</td></tr><tr><td style="text-align:left;"><strong>Hysteria2</strong></td><td style="text-align:left;">UDP (基于 QUIC)</td><td style="text-align:left;">⭐⭐⭐⭐☆ (暴力拥塞控制)</td><td style="text-align:left;">中等</td><td style="text-align:left;"><strong>⭐⭐⭐⭐⭐ (极强抗弱网)</strong></td><td style="text-align:left;"><strong>恶劣丢包网络 / 移动宽带</strong></td></tr></tbody></table><hr><h2 id="🌲-各协议核心原理与适用指南" tabindex="-1">🌲 各协议核心原理与适用指南 <a class="header-anchor" href="#🌲-各协议核心原理与适用指南" aria-label="Permalink to &quot;🌲 各协议核心原理与适用指南&quot;">​</a></h2><h3 id="_1-shadowsocks-2022-专线时代的王者" tabindex="-1">1. Shadowsocks 2022 (专线时代的王者) <a class="header-anchor" href="#_1-shadowsocks-2022-专线时代的王者" aria-label="Permalink to &quot;1. Shadowsocks 2022 (专线时代的王者)&quot;">​</a></h3><p>在企业内网专线（IEPL/IPLC）架构下，流量物理不过墙，因此无需复杂的 TLS 伪装。Shadowsocks 2022 移除了多余的握手握包开销，采用极简的 AEAD 现代加密算法，<strong>吞吐量最大、内存占用最低、手机最省电</strong>。</p><h3 id="_2-vless-xtls-reality-公网抗审查天花板" tabindex="-1">2. VLESS (XTLS-Reality) (公网抗审查天花板) <a class="header-anchor" href="#_2-vless-xtls-reality-公网抗审查天花板" aria-label="Permalink to &quot;2. VLESS (XTLS-Reality) (公网抗审查天花板)&quot;">​</a></h3><p>Reality 技术直接借用海外合规大型网站（如苹果、微软、雅虎）的合法 TLS 证书进行握手伪装，GFW 在探测时无法区分其与真实访问海外巨头网站的流量，目前在公网直连中抗封锁能力位居榜首。</p><h3 id="_3-hysteria2-弱网-恶劣网络救星" tabindex="-1">3. Hysteria2 (弱网/恶劣网络救星) <a class="header-anchor" href="#_3-hysteria2-弱网-恶劣网络救星" aria-label="Permalink to &quot;3. Hysteria2 (弱网/恶劣网络救星)&quot;">​</a></h3><p>基于定制版 QUIC 协议（UDP 传输），内置激进的 BBR 拥塞控制算法。在丢包率高达 20%~30% 的劣质公网环境中，Hysteria2 依然能通过多倍发包跑满几百兆带宽，极度适合移动/校园网等容易限速丢包的网络环境。</p>',12))])}const L=o(y,[["render",f]]);export{T as __pageData,L as default};
